typescript.originalService:
class ProcessSaleService_AutoGenerated {
  /*SystemVariable Start*/
  CurrentCashDesk: CashDesk;
  CurrentStore: Store;
  /*SystemVariable End*/

  /*find an item with provided barcode,
   *if current sale exists and not complete
   *and the item exists and the stock number is greater than 0, create a sales line item
   *and this sale line will be used in other operation.
   *the current sale will include this sale line and the sale line is belong to the current sale.
   *the sale line's quantity is provided quantity and the item stock number will minus the quantity.
   *then caculate the sale line subamount is the item price multiply the quantity.
   *don't forget to save the sale line.
   **/
  enterItem(barcode: number, quantity: number): boolean {
    /*Definition Start*/
    let foundItem: Item = l({
      logic: () =>
        getRepository(Item).find(
          (i: any) =>
            l({
              logic: () => i.Barcode === barcode,
              description: "i.Barcode=barcode",
            }).build().pass,
        ),
      description: "Item.allInstance()->any(i|i.Barcode=barcode)",
    }).build().pass;
    let sale: Sale = l({
      logic: () => this.CurrentSale,
      description: "self.CurrentSale",
    }).build().pass;
    let newSalesLineItem: SalesLineItem;
    let itemAvailable: boolean = l({
      logic: () => StandardOPs.oclIsUndefined(foundItem) === false,
      description: "foundItem.oclIsUndefined()=false",
    })
      .and({
        logic: () => foundItem.StockNumber > 0,
        description: "foundItem.StockNumber>0",
      })
      .and({
        logic: () => StandardOPs.oclIsUndefined(sale) === false,
        description: "sale.oclIsUndefined()=false",
      })
      .and({
        logic: () => sale.IsComplete === false,
        description: "sale.IsComplete=false",
      })
      .build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => itemAvailable,
        description: "itemAvailable",
      }).build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    let newSalesLineItem: SalesLineItem;
    return l({
      execute: () => (newSalesLineItem = new SalesLineItem()),
      description: "newSalesLineItem.oclIsNew()",
    })
      .and({
        execute: () => getRepository(Sale).push(sale),
        description: "Sale.allInstance()->includes(sale)",
      })
      .and({
        execute: () => getRepository(SalesLineItem).push(newSalesLineItem),
        description: "SalesLineItem.allInstance()->includes(newSalesLineItem)",
      })
      .and({
        execute: () => (newSalesLineItem.Quantity = quantity),
        description: "newSalesLineItem.Quantity=quantity",
      })
      .and({
        execute: () => (newSalesLineItem.BelongedItem = foundItem),
        description: "newSalesLineItem.BelongedItem=foundItem",
      })
      .and({
        execute: () => (newSalesLineItem.BelongedSale = sale),
        description: "newSalesLineItem.BelongedSale=sale",
      })
      .and({
        execute: () =>
          (foundItem.StockNumber = foundItem.StockNumber - quantity),
        description: "foundItem.StockNumber=foundItem.StockNumber@pre-quantity",
      })
      .and({
        execute: () =>
          (newSalesLineItem.Subamount = foundItem.Price * quantity),
        description: "newSalesLineItem.Subamount=foundItem.Price*quantity",
      })
      .and({
        execute: () => sale.ContainedSalesLine.push(newSalesLineItem),
        description: "sale.ContainedSalesLine->includes(newSalesLineItem)",
      })
      .and({
        execute: () => (this.CurrentSaleLine = newSalesLineItem),
        description: "self.CurrentSaleLine=newSalesLineItem",
      })
      .and({
        execute: () => true,
        description: "result=true",
      })
      .build().value;
    /*Postcondition End*/
  }
}
export { ProcessSaleService_AutoGenerated };

